def estancia_a_unidades(apps, schema_editor):
    """The old columns were months."""
    Otros = apps.get_model('base', 'Otros')
    for otros in Otros.objects.all():
        otros.estancia_minima = otros.estancia_minima_meses
        otros.estancia_maxima = otros.estancia_maxima_meses
        otros.save(update_fields=['estancia_minima', 'estancia_maxima'])


def estancia_a_meses(apps, schema_editor):
    Otros = apps.get_model('base', 'Otros')
    for otros in Otros.objects.all():
        for campo in ('minima', 'maxima'):
            valor = getattr(otros, f'estancia_{campo}')
            if valor is not None:
                unidad = getattr(otros, f'estancia_{campo}_unidad')
                valor = max(1, round(valor * {'dias': 1 / 30, 'meses': 1, 'anios': 12}[unidad]))
            setattr(otros, f'estancia_{campo}_meses', valor)
        otros.save(update_fields=['estancia_minima_meses', 'estancia_maxima_meses'])


def suites_dentro_del_total(apps, schema_editor):
    """Suites used to be extra rooms; now they are a subset of dobles/individuales.

    Keep each listing's bedroom total by turning the old suites into dobles.
    """
    Dormitorios = apps.get_model('base', 'Dormitorios')
    for dormitorios in Dormitorios.objects.filter(suites__gt=0):
        dormitorios.dobles += dormitorios.suites
        dormitorios.save(update_fields=['dobles'])


